    for (let it = 0; it < 4; it++) {
      for (let v = 0; v < n; v++) { let sx = 0, sy = 0, sz = 0; const b = off[v], e = off[v + 1], c = e - b || 1; for (let q = b; q < e; q++) { const u = adj[q] * 3; sx += P[u]; sy += P[u + 1]; sz += P[u + 2]; } T[v * 3] = sx / c; T[v * 3 + 1] = sy / c; T[v * 3 + 2] = sz / c; }
      const lam = it % 2 ? -0.53 : 0.5; for (let i = 0; i < P.length; i++) P[i] += (T[i] - P[i]) * lam * (1 - M[(i / 3) | 0]);
    }
