  const txt = new TextDecoder().decode(buf), T = [], re = /vertex\\s+([-+\\d.eE]+)\\s+([-+\\d.eE]+)\\s+([-+\\d.eE]+)/g; let m;
  while ((m = re.exec(txt))) T.push(+m[1], +m[2], +m[3]);
