    marble: () => { const n = fbm(2, 4, 5); return (x, y) => { const v = Math.pow((Math.sin((x + y + n(x, y) * 1.6) * Math.PI * 4) + 1) / 2, 6); return mix(hex("#eceae6"), hex("#6b6f78"), v); }; },
